+import 'package:sqflite/sqflite.dart';
+import '../../../../models/local/master/jsa/jsa_model.dart';
+import '../../database_provider.dart';
+
+class JsaDao {
+  final provider = DatabaseProvider.instance;
+  final tableName = jsaModelTableName;
+
+  Future insertAll(List<JsaModel> data) async {
+    final database = await provider.dbMaster;
+
+    try {
+      Batch batch = database.batch();
+      for (var e in data) {
+        batch.insert(
+          tableName,
+          e.toTable(),
+          conflictAlgorithm: ConflictAlgorithm.replace,
+        );
+      }
+      await batch.commit(continueOnError: true, noResult: true);
+      return true;
+    } catch (e) {
+      return false;
+    }
+  }
+
+  Future deleteAll() async {
+    final database = await provider.dbMaster;
+
+    try {
+      await database.delete(tableName);
+      return true;
+    } catch (e) {
+      return false;
+    }
+  }
+
+  Future get({
+    List<String>? columns,
+    String? where,
+    List<String>? whereArgs,
+    String? orderBy,
+    bool? distinct,
+  }) async {
+    final database = await provider.dbMaster;
+
+    return await database.query(
+      tableName,
+      columns: columns,
+      where: where,
+      whereArgs: whereArgs,
+      orderBy: orderBy,
+      distinct: distinct,
+    );
+  }
+
+  Future getWhereDocumentNo({
+    List<String>? columns,
+    required String where,
+  }) async {
+    return await get(
+      columns: columns,
+      where: '$jsaModelColumnDocumentNo = ?',
+      whereArgs: [where],
+    );
+  }
+}
