+import '../../../models/local/master/jsa/jsa_model.dart';
+import '../../../providers/database/dao/master/jsa_dao.dart';
+
+class JsaMasterRepositoryImpl implements JsaMasterRepository {
+  final JsaDao _dao = JsaDao();
+
+  @override
+  Future<bool> insertAll(List<Jsa> data) async {
+    return await _dao.insertAll(
+      data.map((e) => JsaModel.fromEntity(e)).toList(),
+    );
+  }
+
+  @override
+  Future<bool> deleteAll() async {
+    return await _dao.deleteAll();
+  }
+
+  @override
+  Future<List<Jsa>> list({String? projectId, String? divisionId}) async {
+    String? where;
+    List<String>? whereArgs;
+
+    if (projectId != null && projectId.isNotEmpty) {
+      where = '$jsaModelColumnProjectID = ?';
+      whereArgs = [projectId];
+    } else if (divisionId != null && divisionId.isNotEmpty) {
+      where = '$jsaModelColumnDivisionID = ?';
+      whereArgs = [divisionId];
+    }
+
+    final result = await _dao.get(
+      where: where,
+      whereArgs: whereArgs,
+      orderBy: '$jsaModelColumnDocumentNo ASC',
+    );
+
+    if (result != null && result is List) {
+      return result.map((e) => JsaModel.fromTable(e)).toList();
+    }
+    return [];
+  }
+
+  @override
+  Future<Jsa> getByDocumentNo(String documentNo) async {
+    final result = await _dao.getWhereDocumentNo(where: documentNo);
+
+    if (result != null && result is List && result.isNotEmpty) {
+      return JsaModel.fromTable(result.first);
+    }
+    return Jsa();
+  }
+}
