+import 'package:flutter_test/flutter_test.dart';
+import 'package:wsafe/data/models/local/master/jsa/jsa_model.dart';
+import 'package:wsafe/domain/entities/local/master/jsa/jsa.dart';
+import 'package:wsafe/domain/repositories/local/master/jsa_master_repository.dart';
+import 'package:wsafe/domain/usecases/local/master/master_data_detail_jsa_by_document_no_use_case.dart';
+import 'package:wsafe/domain/usecases/local/master/master_data_list_jsa_use_case.dart';
+
+void main() {
+  test('JSA model parses sample response and maps to table', () {
+    final json = {
+      'id': '3a87735b-44ea-4430-a2c7-c0cb0cfb055a',
+      'documentNo': 'JSA-102026-0009',
+      'divisionID': '7bb7fbf2-d913-4f15-b219-c3b0e4baad9b',
+      'divisionName': 'Infrastructure Division',
+      'projectID': '8506c14a-0404-46ae-8f94-6dc84b53d461',
+      'projectName': 'AB1 Sungai Kera',
+      'location': 'rgretr',
+      'jobID': '3320DC79-BD09-4EFB-97A9-513E25796BD2',
+      'job': 'Berthing Operation',
+    };
+
+    final model = JsaModel.fromJson(json);
+
+    expect(model.id, '3a87735b-44ea-4430-a2c7-c0cb0cfb055a');
+    expect(model.documentNo, 'JSA-102026-0009');
+    expect(model.divisionName, 'Infrastructure Division');
+    expect(model.projectName, 'AB1 Sungai Kera');
+    expect(model.job, 'Berthing Operation');
+
+    final table = JsaModel.fromEntity(model).toTable();
+    expect(table['id'], '3a87735b-44ea-4430-a2c7-c0cb0cfb055a');
+    expect(table['documentNo'], 'JSA-102026-0009');
+
+    final roundTrip = JsaModel.fromTable(table);
+    expect(roundTrip.documentNo, 'JSA-102026-0009');
+    expect(roundTrip.projectID, '8506c14a-0404-46ae-8f94-6dc84b53d461');
+  });
+
+  test('JSA usecases return list and detail by documentNo', () async {
+    final fakeRepo = _FakeJsaMasterRepository();
+    final listUseCase = MasterDataListJsaUseCase(fakeRepo);
+    final detailUseCase = MasterDataDetailJsaByDocumentNoUseCase(fakeRepo);
+
+    final list = await listUseCase
+        .execute('8506c14a-0404-46ae-8f94-6dc84b53d461');
+    expect(list.length, 1);
+    expect(list.first.documentNo, 'JSA-102026-0009');
+
+    final detail = await detailUseCase.execute('JSA-102026-0009');
+    expect(detail.documentNo, 'JSA-102026-0009');
+    expect(detail.job, 'Berthing Operation');
+  });
+}
+
+class _FakeJsaMasterRepository implements JsaMasterRepository {
+  final Jsa _sample = Jsa(
+    id: '3a87735b-44ea-4430-a2c7-c0cb0cfb055a',
+    documentNo: 'JSA-102026-0009',
+    divisionID: '7bb7fbf2-d913-4f15-b219-c3b0e4baad9b',
+    divisionName: 'Infrastructure Division',
+    projectID: '8506c14a-0404-46ae-8f94-6dc84b53d461',
+    projectName: 'AB1 Sungai Kera',
+    location: 'rgretr',
+    jobID: '3320DC79-BD09-4EFB-97A9-513E25796BD2',
+    job: 'Berthing Operation',
+  );
+
+  @override
+  Future<bool> deleteAll() async => true;
+
+  @override
+  Future<Jsa> getByDocumentNo(String documentNo) async => _sample;
+
+  @override
+  Future<bool> insertAll(List<Jsa> data) async => true;
+
+  @override
+  Future<List<Jsa>> list({String? projectId, String? divisionId}) async =>
+      [_sample];
+}
